import (
    "bytes"
    "fmt"
)

func main() {
    engine := NewStorageEngine()

    // Append logs
    for i := uint64(1); i <= 5; i++ {
        err := engine.AppendLog(LogEntry{
            Index: i,
            Term:  1,
            Data:  []byte(fmt.Sprintf("cmd-%d", i)),
        })
        if err != nil {
            panic(err)
        }
    }

    entry, err := engine.ReadLog(3)
    if err != nil || !bytes.Equal(entry.Data, []byte("cmd-3")) {
        panic("failed to read log entry 3")
    }

    // Apply snapshot and compact
    err = engine.ApplySnapshot(Snapshot{
        LastIndex: 3,
        LastTerm:  1,
        State:     []byte("snapshot-state"),
    })
    if err != nil {
        panic(err)
    }

    println("Go Multi-Module Raft WAL Test Passed!")
}
